import { randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const dataDir = path.join(process.cwd(), "data");
const dataFile = path.join(dataDir, "books.json");

async function readBooks() {
  try {
    const raw = await readFile(dataFile, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch (error) {
    if (error && error.code === "ENOENT") {
      return [];
    }
    throw error;
  }
}

async function writeBooks(books) {
  await mkdir(dataDir, { recursive: true });
  await writeFile(dataFile, JSON.stringify(books, null, 2) + "\n", "utf8");
}

export async function listBooks() {
  const books = await readBooks();
  return books.sort((a, b) => (b.addedAt || "").localeCompare(a.addedAt || ""));
}

export async function getBook(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || "").trim(),
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeBooks(books);
  return book;
}

export async function markFinished(id) {
  const books = await readBooks();
  const book = books.find((item) => item.id === id);
  if (!book) {
    return null;
  }
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await writeBooks(books);
  return book;
}

