:root {
  color-scheme: light;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e5e4;
  --paper: #fafaf9;
  --card: #ffffff;
  --accent: #9a3412;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
  font-family: Georgia, "Times New Roman", serif;
  line-height: 1.5;
}

a {
  color: inherit;
}

.site-header,
main {
  width: min(720px, calc(100% - 2rem));
  margin: 0 auto;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
}

.brand {
  font-size: 1.25rem;
  text-decoration: none;
}

.button,
button {
  display: inline-block;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: white;
  text-decoration: none;
  font: inherit;
  font-size: 0.95rem;
  padding: 0.45rem 0.8rem;
  cursor: pointer;
}

.button.secondary,
button.secondary {
  background: transparent;
  color: var(--ink);
}

h1,
h2 {
  font-weight: normal;
  letter-spacing: -0.02em;
}

h1 {
  margin: 0 0 1.5rem;
  font-size: 2rem;
}

h2 {
  margin: 0 0 0.75rem;
  font-size: 1.15rem;
  color: var(--muted);
}

section + section {
  margin-top: 2rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.75rem;
}

.book-card {
  display: block;
  background: var(--card);
  border: 1px solid var(--line);
  padding: 0.9rem 1rem;
  text-decoration: none;
}

.book-card strong {
  display: block;
}

.book-card span,
.muted,
.empty {
  color: var(--muted);
}

.book-detail {
  background: var(--card);
  border: 1px solid var(--line);
  padding: 1.25rem;
}

.book-detail p {
  white-space: pre-wrap;
}

.actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  margin-top: 1.25rem;
}

form.stack {
  display: grid;
  gap: 0.9rem;
  max-width: 32rem;
}

label {
  display: grid;
  gap: 0.3rem;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--line);
  background: white;
  color: var(--ink);
}

.error {
  color: var(--accent);
}

