import { listBooks } from "@/lib/books";

export const dynamic = "force-dynamic";

function BookList({ books }) {
  if (books.length === 0) {
    return <p className="empty">Nothing here yet.</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id}>
          <a className="book-card" href={`/books/${book.id}`}>
            <strong>{book.title}</strong>
            <span>{book.author}</span>
          </a>
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage() {
  const books = await listBooks();
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <>
      <h1>What I'm reading</h1>
      <section>
        <h2>Currently reading</h2>
        <BookList books={reading} />
      </section>
      <section>
        <h2>Finished</h2>
        <BookList books={finished} />
      </section>
    </>
  );
}

