      <h1>Add a book</h1>
      {missing ? <p className="error">Title and author are required.</p> : null}
      <form className="stack" action={createBook}>
        <label>
          Title
          <input name="title" required />
        </label>
        <label>
          Author
          <input name="author" required />
        </label>
        <label>
          Notes
          <textarea name="notes" rows={5} />
        </label>
        <div>
          <button type="submit">Save book</button>
        </div>
      </form>
    </>
  );
}

