import { notFound } from "next/navigation";
import { finishBook } from "@/app/actions";
import { getBook } from "@/lib/books";

export const dynamic = "force-dynamic";

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);

  if (!book) {
    notFound();
  }

  return (
    <>
      <h1>{book.title}</h1>
      <article className="book-detail">
        <p>
          <strong>Author.</strong> {book.author}
        </p>
        <p>
          <strong>Status.</strong>{" "}
          {book.status === "finished" ? "Finished" : "Currently reading"}
        </p>
        <p>
          <strong>Notes.</strong>
          <br />
          {book.notes ? book.notes : <span className="muted">No notes yet.</span>}
        </p>
        <div className="actions">
          {book.status !== "finished" ? (
            <form action={finishBook}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit">Mark as finished</button>
            </form>
          ) : null}
          <a className="button secondary" href="/">
            Back to list
          </a>
        </div>
      </article>
    </>
  );
}

